(()=>{
 const reduce=matchMedia('(prefers-reduced-motion:reduce)').matches;
 const common={speed:reduce?0:420,grabCursor:true,simulateTouch:true,allowTouchMove:true,touchStartPreventDefault:false,preventClicks:true,preventClicksPropagation:true,threshold:5,longSwipesRatio:.25,a11y:{enabled:true}};
 if(window.Swiper){document.querySelectorAll('.work-carousel').forEach(el=>new Swiper(el,{...common,slidesPerView:1.06,spaceBetween:20,breakpoints:{721:{slidesPerView:2,spaceBetween:30}},navigation:{prevEl:el.parentElement.querySelector('.work-prev'),nextEl:el.parentElement.querySelector('.work-next')},pagination:{el:el.parentElement.querySelector('.work-pagination'),clickable:true}}));document.querySelectorAll('.review-swiper').forEach(el=>new Swiper(el,{...common,slidesPerView:1.08,spaceBetween:18,breakpoints:{721:{slidesPerView:2,spaceBetween:22},1100:{slidesPerView:3,spaceBetween:25}},navigation:{prevEl:el.parentElement.querySelector('[data-review-direction="-1"]'),nextEl:el.parentElement.querySelector('[data-review-direction="1"]')}}));}
 const phone=document.querySelector('.phone-app');if(!phone)return;const original=phone.innerHTML;
 const views={access:{title:'Vehicle access',label:'Access groups',stat:'You’re in control.',icon:'car',rows:[['Staff','Weekdays'],['Residents','Authorised'],['Visitors','Approved']]},payments:{title:'Parking payments',label:'Payment activity',stat:'Payments connected.',icon:'card',rows:[['Contactless','Paid'],['QR payment','Paid'],['Hotel guest','Validated']]},reports:{title:'Parking reports',label:'Your reporting',stat:'Your site at a glance.',icon:'chart',rows:[['Vehicle activity','This week'],['Reporting','Up to date']]}};
 document.querySelectorAll('[data-dashboard]').forEach(b=>b.addEventListener('click',()=>{const key=b.dataset.dashboard;if(key==='overview'){phone.innerHTML=original;return;}phone.innerHTML=original;const v=views[key];phone.querySelector('h3').textContent=v.title;phone.querySelector('.phone-stat>span').textContent=v.label;phone.querySelector('.phone-stat strong').textContent=v.stat;phone.querySelector('.phone-stat use').setAttribute('href','#i-'+v.icon);phone.querySelector('h4').textContent=key==='reports'?'Weekly overview':'Recent activity';phone.querySelectorAll('.phone-event').forEach(x=>x.remove());const extra=document.createElement('div');extra.className='phone-view-extra';extra.innerHTML=v.rows.map(row=>`<div class="phone-view-row"><span>${row[0]}</span><strong>${row[1]}</strong></div>`).join('');if(key==='reports')extra.innerHTML='<div class="phone-view-chart" aria-label="Weekly activity">'+[30,48,70,90,65,80,40].map(h=>`<i style="--h:${h}%"></i>`).join('')+'</div>';phone.querySelector('h4').after(extra);phone.querySelector('.phone-action').textContent=key==='payments'?'View payments':key==='reports'?'View reports':'Manage access';phone.querySelectorAll('.phone-bottom-nav>span').forEach((s,i)=>s.classList.toggle('is-active',key==='access'?i===1:i===0));}));
 phone.addEventListener('click',e=>{if(!e.target.closest('.phone-action'))return;const current=document.querySelector('[data-dashboard].is-active')?.dataset.dashboard||'overview';const next=current==='overview'?'access':current==='access'?'payments':current==='payments'?'reports':'overview';document.querySelector(`[data-dashboard="${next}"]`)?.click();});
})();
